begin;
create extension if not exists pgtap with schema extensions;
set local search_path = extensions, public, pg_catalog;
select plan(15);
select ok(not has_function_privilege('anon','public.begin_admin_password_reset(uuid,uuid)','EXECUTE'), 'anonymous cannot start resets');
select ok(not has_function_privilege('authenticated','public.begin_admin_password_reset(uuid,uuid)','EXECUTE'), 'authenticated clients cannot start resets directly');
select ok(has_function_privilege('service_role','public.begin_admin_password_reset(uuid,uuid)','EXECUTE'), 'only the server role can start guarded resets');
select ok(not has_table_privilege('service_role','private.admin_password_reset_guards','SELECT'), 'server role cannot bypass guard routines');
select ok(not has_function_privilege('authenticated','public.finish_admin_password_reset(uuid,uuid,uuid)','EXECUTE'), 'authenticated clients cannot finish guards');
select throws_ok($$select public.begin_admin_password_reset('00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003')$$,'P0001','Account role is not eligible for reset','non-admin actor is rejected');
select throws_ok($$select public.begin_admin_password_reset('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001')$$,'P0001','Invalid account selection','self reset is rejected');
set local role service_role;
select lives_ok($$select set_config('barber.test_guard',public.begin_admin_password_reset('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002')::text,true)$$,'server starts guarded reset');
reset role;
select is((select count(*) from private.admin_password_reset_guards where actor_id='00000000-0000-4000-8000-000000000001' and target_id='00000000-0000-4000-8000-000000000002'),1::bigint,'guard persists until completion');
select throws_ok($$update auth.users set raw_app_meta_data=jsonb_set(raw_app_meta_data,'{role}','"admin"') where id='00000000-0000-4000-8000-000000000002'$$,'P0001','Role change blocked by password reset guard','target role change is blocked');
select throws_ok($$update auth.users set raw_app_meta_data=jsonb_set(raw_app_meta_data,'{role}','"manager"') where id='00000000-0000-4000-8000-000000000001'$$,'P0001','Role change blocked by password reset guard','actor role change is blocked');
select lives_ok($$update auth.users set raw_user_meta_data=coalesce(raw_user_meta_data,'{}'::jsonb)||'{"guard_test":true}'::jsonb where id='00000000-0000-4000-8000-000000000002'$$,'unrelated metadata update remains available');
set local role service_role;
select lives_ok($$select public.finish_admin_password_reset(current_setting('barber.test_guard')::uuid,'00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002')$$,'server completes reset and audit');
reset role;
select is((select count(*) from private.admin_password_reset_guards where id=current_setting('barber.test_guard')::uuid),0::bigint,'successful completion releases the guard');
select lives_ok($$update auth.users set raw_app_meta_data=jsonb_set(raw_app_meta_data,'{role}','"admin"') where id='00000000-0000-4000-8000-000000000002'$$,'role change succeeds after guard is released');
select * from finish();
rollback;
